/**
 * Pure vocabulary of the read barrier: the session roles, the path-opening
 * capabilities that can refuse a read, the resolved per-session policy, the
 * durable refusal record, the composition census one session was granted, and
 * the host attestation that puts the checks outside the harness account.
 *
 * @module @deepseek-ai/dsh-read-barrier/types
 */

import type { ToolAuthority } from '@deepseek-ai/dsh-tools/types'

/**
 * Authority a session holds against the barrier. `implementer` and `judge` are
 * denied every directory the barrier owns and every declared tool authority —
 * the implementer so it cannot read the standard it is measured against, the
 * judge so it cannot reach the audited session's log or the check instructions
 * behind the evidence it was handed. `validator` and `unrestricted` are denied
 * nothing, and `unrestricted` is what a session holds without a reservation.
 * Which directories and authorities a role may hold is a security invariant,
 * never a deployment choice.
 */
export type ReadBarrierRole = 'implementer' | 'judge' | 'validator' | 'unrestricted'

/**
 * Capability seam that refused one read. Each member names a seam that opens
 * paths and can therefore decide a refusal in the operation that opens them.
 */
export type ReadBarrierCapability = 'fs' | 'shell' | 'subprocess' | 'terminal'

/**
 * The barrier's complete decision inputs for one session, resolved once per
 * capability call. `denied` lists every directory the role may not read,
 * canonicalized only at the moment of the containment test.
 */
export interface ReadBarrierPolicy {
  /** Authority the calling session holds. */
  readonly role: ReadBarrierRole
  /** The barrier's own validator-owned root, always the first denied directory. */
  readonly root: string
  /** Every denied directory: the root, the configured extras, the registered ones, and those registered for this session. */
  readonly denied: readonly string[]
  /**
   * The session's own workspace, granted whole. A denied directory that is a
   * STRICT ancestor of it denies the rest of that ancestor's subtree and leaves
   * this directory readable; a denied directory that IS this one, or that lies
   * inside it, denies as it would without the grant. Absent for a session
   * created without a cwd and for every agentless call, which grant nothing.
   */
  readonly granted?: string
}

/**
 * One refusal, as the `read-barrier/denied` session event carries it. The path
 * is already in the log inside the model's own `tool/call` arguments, so the
 * record adds evidence and no new disclosure.
 */
export interface ReadBarrierDenial {
  /** Self-declared payload version. */
  readonly version: 1
  /** Role the refused session held. */
  readonly role: ReadBarrierRole
  /** Seam that refused the read. */
  readonly capability: ReadBarrierCapability
  /** Model-facing path of the refused target, exactly as the refusal reported it. */
  readonly displayPath: string
  /** The barrier root in force when the read was refused. */
  readonly root: string
}

/**
 * What a preset roster declares about one agent's composition. The roster is
 * the only authority that can raise or lower a session's role, because only
 * the composition knows which preset was actually mounted.
 */
export interface ReadBarrierComposition {
  /** Preset the agent joined, recorded verbatim in the scope census. */
  readonly presetId: string
  /**
   * Role the preset declared, absent when it declared none. A preset that
   * declares no role leaves the reservation to decide, so a validator can
   * still make an unmarked composition the implementer.
   */
  readonly role?: ReadBarrierRole
}

/**
 * Path-opening capability the scope census reports enforcement for. It extends
 * {@link ReadBarrierCapability} with the two executors the harness cannot fence
 * in-process and must therefore refuse to start instead of denying a read.
 */
export type ReadBarrierEnforcedCapability = ReadBarrierCapability | 'subagent' | 'workflow'

/**
 * What one path-opening capability does about the barrier in this composition:
 * it denies at the operation that opens paths, it is composed and denies
 * nothing, or the composition does not have it at all.
 */
export type ReadBarrierEnforcementState = 'denied-at-executor' | 'unenforced' | 'not-composed'

/** One capability's enforcement decision, as the scope census records it. */
export interface ReadBarrierEnforcementEntry {
  /** The path-opening capability. */
  readonly capability: ReadBarrierEnforcedCapability
  /** What that capability does about the barrier. */
  readonly state: ReadBarrierEnforcementState
  /**
   * Why a composed capability enforces nothing, absent whenever it does. The
   * capability itself supplies it — the host's backend cannot express the
   * denial, or the deployment claims an isolation that asks nothing of it — so
   * a certificate refused over this census can say what was missing instead of
   * only which capability was silent.
   */
  readonly reason?: string
}

/**
 * Isolation a deployment intends its certificates to claim, which decides
 * whether a capability that cannot be confined in-process refuses to run or
 * merely records that it enforces nothing. It repeats `CertificateIsolation`'s
 * members rather than importing them: `@deepseek-ai/dsh-verification` reads this
 * package, so the dependency cannot run the other way.
 */
export type ReadBarrierIsolationClaim = 'none' | 'process' | 'host'

/** One visible tool and the authorities its definition declares. */
export interface ReadBarrierCensusEntry {
  /** Tool name as the session's registry view resolves it. */
  readonly name: string
  /** Authorities the definition declared, empty for an ordinary tool. */
  readonly authority: readonly ToolAuthority[]

import type { Context } from '@deepseek-ai/cordis'
import {
  CallId,
  LlmAdapter,
  ReasoningEffortId,
  type GenerateOptions,
  type LlmResolvedModelInfo,
  type StreamChunk,
} from '@deepseek-ai/dsh-llm'

const HIGH = ReasoningEffortId('high')
const OFF = ReasoningEffortId('off')

/** Keyless headless-agent adapter: one real bash call followed by a final answer. */
class CliMockAdapter extends LlmAdapter {
  override async resolveModel(provider: string, model: string): Promise<LlmResolvedModelInfo> {
    return {
      provider,
      id: model,
      name: model,
      reasoning: {
        efforts: [
          { id: OFF, name: 'Off' },
          { id: HIGH, name: 'High' },
        ],
        defaultEffort: HIGH,
      },
    }
  }

  async * stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    if (process.env.DSH_CLI_MOCK_FAILURE === '1') {
      yield { type: 'finish', reason: { kind: 'error', failure: { code: 'SERVER', message: 'CLI mock provider failed' } } }
      return
    }
    const toolResult = options.messages.at(-1)?.content.find(block => block.type === 'tool-result')
    if (toolResult === undefined) {
      const args = JSON.stringify({ command: 'printf CLI_TOOL_ROUND_TRIP', description: 'Prove the CLI tool round trip.' })
      yield { type: 'block-start', index: 0, blockType: 'tool-call' }
      yield { type: 'tool-call-delta', index: 0, id: CallId('cli-smoke-call'), name: 'bash', argumentsDelta: args }
      yield { type: 'block-end', index: 0, block: { type: 'tool-call', id: CallId('cli-smoke-call'), name: 'bash', arguments: args } }
      yield { type: 'usage', usage: { inputTokens: 11, outputTokens: 3, cacheReadTokens: 2 } }
      yield { type: 'finish', reason: { kind: 'tool-calls' } }
      return
    }

    const toolText = toolResult.content
      .filter(block => block.type === 'text')
      .map(block => block.text)
      .join('')
    const reply = `CLI tool round trip complete: ${toolText.trim()}`
    yield { type: 'block-start', index: 0, blockType: 'text' }
    yield { type: 'text-delta', index: 0, text: reply }
    yield { type: 'block-end', index: 0, block: { type: 'text', text: reply } }
    yield { type: 'usage', usage: { inputTokens: 7, outputTokens: 5, reasoningTokens: 1 } }
    yield { type: 'finish', reason: { kind: 'stop' } }
  }
}

export const name = 'cli-mock-llm'
export const inject = ['llm']

/** Register the keyless `cli-mock` adapter. */
export function apply(ctx: Context): void {
  ctx.llm.registerAdapter(['cli-mock'], new CliMockAdapter())
  ctx.on('agent/request', async ({ step }, next) => {
    const config = await next()
    return step === 2 ? { ...config, reasoningEffort: OFF } : config
  })
}

/**
 * Keyless adapter that plays a cell agent probing the run directory its
 * workspace sits in. Its first step runs one bash command that tries to list the
 * parent, read the run's plan, and read a sibling cell, then reads and writes
 * its own workspace and writes the candidate the task's cased check measures;
 * its second step reads the plan again through the `read` tool, which is the
 * seam that records a refusal. The markers below are pinned by the e2e, so keep
 * them and its literals together.
 */

import type { Context } from '@deepseek-ai/cordis'
import {
  CallId,
  LlmAdapter,
  type GenerateOptions,
  type LlmResolvedModelInfo,
  type StreamChunk,
} from '@deepseek-ai/dsh-llm'

/**
 * Prefix of the line carrying what the confined shell listed in the parent
 * directory, one space-separated entry each. The names, not the count, are what
 * the e2e reads: a backend that refuses the listing outright and one that mounts
 * an empty directory with the workspace bound back into it produce different
 * counts and the same absence of every sibling name.
 */
const PARENT_LISTING_MARKER = 'PARENT-LISTING-'

/** What the tool result says when the confined shell read the run's plan, and when it could not. */
const PLAN_LEAKED_MARKER = 'PLAN-LEAKED'
const PLAN_DENIED_MARKER = 'PLAN-DENIED'

/** What the tool result says when the confined shell read a sibling cell's file, and when it could not. */
const SIBLING_LEAKED_MARKER = 'SIBLING-LEAKED'
const SIBLING_DENIED_MARKER = 'SIBLING-DENIED'

/** What the tool result says when the confined shell read and wrote its own workspace. */
const OWN_READ_MARKER = 'OWN-READ-OK'
const OWN_WRITE_MARKER = 'OWN-WRITE-OK'

/** What the tool result says once the candidate the cased check measures is in the workspace. */
const CANDIDATE_WRITTEN_MARKER = 'CANDIDATE-WRITTEN'

/**
 * The candidate: three labelled lines, one per input channel a case can feed.
 * `$(cat)` reads the case's stdin, which the runner closes after writing it, so
 * a case without stdin ends the line after `stdin=`.
 */
const CANDIDATE_SCRIPT = [
  'printf \'argv=%s\\n\' "$*"',
  'printf \'stdin=%s\\n\' "$(cat)"',
  'printf \'file=%s\\n\' "$(cat input.txt 2>/dev/null)"',
].join('\n')

/**
 * One command, so a single transcript records everything the confined process
 * could reach. Every probe is written to fail silently: a backend that denies by
 * hiding the directory and one that denies by refusing the open must both land
 * on the denied marker rather than on a shell error. The candidate is written
 * last, through a quoted heredoc so the shell expands nothing at write time.
 */
const PROBE_COMMAND = [
  [
    `echo ${PARENT_LISTING_MARKER}$(ls -A .. 2>/dev/null | tr '\\n' ' ')`,
    `if cat ../plan.json > leaked-plan.txt 2>/dev/null; then echo ${PLAN_LEAKED_MARKER}; else echo ${PLAN_DENIED_MARKER}; fi`,
    `if cat ../cell-sibling/src.js > leaked-sibling.txt 2>/dev/null; then echo ${SIBLING_LEAKED_MARKER}; else echo ${SIBLING_DENIED_MARKER}; fi`,
    `if grep -q own-file own.txt 2>/dev/null; then echo ${OWN_READ_MARKER}; fi`,
    `if touch MARKER && test -f MARKER; then echo ${OWN_WRITE_MARKER}; fi`,
  ].join('; '),
  'cat > channels.sh <<\'CANDIDATE\'',
  CANDIDATE_SCRIPT,
  'CANDIDATE',
  `if test -f channels.sh; then echo ${CANDIDATE_WRITTEN_MARKER}; fi`,
].join('\n')

/** The path the second step reads through the `read` tool, which is where a refusal is recorded. */
const PLAN_PATH = '../plan.json'

class SealedCellAdapter extends LlmAdapter {
  override async resolveModel(provider: string, model: string): Promise<LlmResolvedModelInfo> {
    return { provider, id: model, name: model }
  }

  async * stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const results = options.messages.filter(message => (message.content ?? []).some(block => block.type === 'tool-result'))
    if (results.length === 0) {
      yield * call('probe-shell', 'bash', { command: PROBE_COMMAND, description: 'Probe the run directory, then create MARKER and channels.sh.' })
      return
    }
    if (results.length === 1) {
      yield * call('probe-read', 'read', { file_path: PLAN_PATH })
      return
    }
    yield * reply('TASK COMPLETE')
  }
}

/** One tool call as the canonical block sequence of a step that stops on tool calls. */
function * call(id: string, name: string, args: object): Generator<StreamChunk> {
  const serialized = JSON.stringify(args)
  yield { type: 'block-start', index: 0, blockType: 'tool-call' }
  yield { type: 'tool-call-delta', index: 0, id: CallId(id), name, argumentsDelta: serialized }
  yield { type: 'block-end', index: 0, block: { type: 'tool-call', id: CallId(id), name, arguments: serialized } }
  yield { type: 'usage', usage: { inputTokens: 19, outputTokens: 7 } }
  yield { type: 'finish', reason: { kind: 'tool-calls' } }
}

/** One text answer as the canonical block sequence of a stopped step. */
function * reply(text: string): Generator<StreamChunk> {
  yield { type: 'block-start', index: 0, blockType: 'text' }
  yield { type: 'text-delta', index: 0, text }
  yield { type: 'block-end', index: 0, block: { type: 'text', text } }
  yield { type: 'usage', usage: { inputTokens: 21, outputTokens: 2 } }
  yield { type: 'finish', reason: { kind: 'stop' } }
}

export const name = 'sealed-cell-llm'

export const inject = ['llm']

/**
 * Register the keyless `sealed-cell` adapter.
 * @param ctx - the plugin context carrying the LLM runtime.
 */
export function apply(ctx: Context): void {
  ctx.llm.registerAdapter(['sealed-cell'], new SealedCellAdapter())
}
